    ZEBAK_ACID_TILE("Zebak Acid Tile", ToaMistakeTrackerConfig::zebakAcidMessage, "I'm drowning in acid!",
            "zebak-acid.png"),
    ZEBAK_BLOOD_CLOUD("Zebak Blood Cloud", ToaMistakeTrackerConfig::zebakBloodMessage, "I'm on a blood cloud!",
