    ZEBAK_EARTHQUAKE("Zebak Scream", ToaMistakeTrackerConfig::zebakScreamMessage, "Nihil!", "zebak-scream.png"),
    ZEBAK_WAVE("Zebak Wave", ToaMistakeTrackerConfig::zebakWaveMessage, "I'm surfing!", "zebak-wave.png"),

