    KEPHRI_BOMB("Kephri Bomb", ToaMistakeTrackerConfig::kephriBombMessage, "I'm exploding!", "kephri-bomb.png"),
    KEPHRI_SWARM_HEAL("Kephri Swarm Heal", (config) -> "The swarms are going in!", "The swarms are going in!",
